// Phase 6: find leads that have gone quiet.
// A lead is "silent" when:
//   - it is still open (not WON/LOST/ESCALATED)
//   - we sent them something at least SILENCE_HOURS ago
//   - they have not replied since (no inbound message newer than our last outbound)
//   - we have not already escalated them for silence
const SILENCE_HOURS = 12;
const cutoff = Date.now() - SILENCE_HOURS * 60 * 60 * 1000;

const leads = $('Fetch Open Leads').all().map(i => i.json).filter(l => l && l.email);
const logs  = $('Fetch Recent Comms').all().map(i => i.json).filter(l => l && l.lead_email);

const byLead = {};
for (const row of logs) {
  const key = String(row.lead_email);
  (byLead[key] = byLead[key] || []).push(row);
}

const out = [];
for (const lead of leads) {
  const rows = byLead[String(lead.email)] || [];
  if (!rows.length) continue;

  const ts = (r) => new Date(r.created_at || 0).getTime();
  const outbound = rows.filter(r => r.direction === 'outbound').sort((a,b) => ts(b) - ts(a));
  const inbound  = rows.filter(r => r.direction === 'inbound').sort((a,b) => ts(b) - ts(a));
  if (!outbound.length) continue;

  const lastOut = ts(outbound[0]);
  const lastIn  = inbound.length ? ts(inbound[0]) : 0;

  // Customer already replied after our last message -> not silent.
  if (lastIn >= lastOut) continue;
  // Not silent long enough yet.
  if (lastOut > cutoff) continue;
  // Already chased for silence -> don't spam the team every hour.
  if (rows.some(r => String(r.message || '').startsWith('[SILENCE-ESCALATED]'))) continue;

  out.push({ json: {
    email: lead.email,
    name: lead.name || null,
    phone: lead.phone || null,
    ai_score: lead.ai_score ?? null,
    status: lead.status || null,
    vehicle_interest: lead.vehicle_interest || null,
    hours_silent: Math.floor((Date.now() - lastOut) / 3600000),
    last_outbound_at: outbound[0].created_at,
    last_outbound_message: String(outbound[0].message || '').substring(0, 300)
  } });
}

// Highest-value silent leads first.
out.sort((a, b) => (b.json.ai_score || 0) - (a.json.ai_score || 0));
return out;

// Every node whose success this run is about to claim.
const CLAIMED = [
  { node: 'Trigger Lead Escalation', what: 'lead escalation handed to the sales team', critical: true },
  { node: 'Mark as Escalated',       what: '[SILENCE-ESCALATED] marker row that stops hourly re-escalation', critical: false },
];

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 300) };
  }
  return { ...c, ok: true };
}

const results  = CLAIMED.map(check);
const dropped  = results.filter(r => !r.ok);
const fatal    = dropped.filter(r => r.critical);

const status = fatal.length  ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

return [{ json: {
  ...( $input.first().json || {} ),
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  dropped.map(r => r.what + ' — ' + r.why),
    note: dropped.length
      ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
      : 'all ' + results.length + ' claimed steps verified',
  },
}, pairedItem: { item: 0 } }];

